+package main
+
+import (
+	"fmt"
+	"os"
+	"path/filepath"
+
+	"github.com/rosedblabs/rosedb/v2"
+)
+
+func main() {
+	dir, _ := os.MkdirTemp("", "rosedb-batch-test")
+	defer os.RemoveAll(dir)
+
+	options := rosedb.DefaultOptions
+	options.DirPath = dir
+	
+	db, err := rosedb.Open(options)
+	if err != nil {
+		panic(err)
+	}
+	defer db.Close()
+
+	batch := db.NewBatch(rosedb.DefaultBatchOptions)
+	key := []byte("test-key")
+	value1 := []byte("value1")
+	value2 := []byte("value2")
+	
+	fmt.Printf("Putting key with value1: %s\n", string(value1))
+	err = batch.Put(key, value1)
+	if err != nil {
+		panic(err)
+	}
+	
+	fmt.Printf("Putting same key with value2: %s\n", string(value2))
+	err = batch.Put(key, value2)
+	if err != nil {
+		panic(err)
+	}
+	
+	res, err := batch.Get(key)
+	if err != nil {
+		panic(err)
+	}
+	fmt.Printf("Value retrieved from batch: %s\n", string(res))
+	
+	err = batch.Commit()
+	if err != nil {
+		panic(err)
+	}
+	
+	res2, err := db.Get(key)
+	if err != nil {
+		panic(err)
+	}
+	fmt.Printf("Value retrieved from db after commit: %s\n", string(res2))
+	
+	if string(res2) == string(value2) {
+		fmt.Println("SUCCESS: Correct value stored")
+	} else {
+		fmt.Println("ERROR: Incorrect value stored")
+	}
+}
